import { Queue, Worker, UnrecoverableError } from 'bullmq';
import { createHash } from 'node:crypto';
import { redis } from './redis';
import { pgPool } from './postgres';

export interface CanonicalEvent {
  eventId: string;
  idempotencyKey: string;
  source: 'pos' | 'crm' | 'erp' | 'zalo_oa';
  eventType: string;
  occurredAt: string;
  entityPhoneE164?: string;
  payload: Record<string, unknown>;
}

export const eltPosQueue = new Queue<CanonicalEvent>('elt-pos-to-crm-zalo', {
  connection: redis,
  defaultJobOptions: {
    attempts: 5,
    backoff: { type: 'exponential', delay: 1500 },
    removeOnComplete: { age: 3600, count: 2000 },
    removeOnFail: false, // Giữ nguyên job lỗi trong Failed/DLQ để điều tra & Replay
  },
});

export function buildDeterministicKey(source: string, externalId: string, eventType: string): string {
  const raw = `${source}:${externalId}:${eventType}`;
  return createHash('sha256').update(raw).digest('hex').slice(0, 32);
}

export const eltWorker = new Worker<CanonicalEvent>(
  'elt-pos-to-crm-zalo',
  async (job) => {
    const evt = job.data;
    const lockKey = `idemp:done:${evt.idempotencyKey}`;
    const inflightKey = `idemp:lock:${evt.idempotencyKey}`;

    // Lớp 1: Chặn nhanh trong Redis nếu event đã hoàn tất trước đó
    if (await redis.get(lockKey)) return { skipped: true, reason: 'already_done_redis' };

    const acquired = await redis.set(inflightKey, job.id || '1', 'EX', 60, 'NX');
    if (!acquired) throw new Error('Concurrent duplicate in flight, retry with backoff');

    const client = await pgPool.connect();
    try {
      await client.query('BEGIN');
      // Lớp 2: Khóa vĩnh viễn trong Postgres + chặn sự kiện cũ đến trễ
      const ledgerRes = await client.query(
        `INSERT INTO elt_idempotency_ledger (idempotency_key, source, event_type, occurred_at)
         VALUES ($1, $2, $3, $4) ON CONFLICT (idempotency_key) DO NOTHING RETURNING id`,
        [evt.idempotencyKey, evt.source, evt.eventType, evt.occurredAt]
      );
      if (ledgerRes.rowCount === 0) {
        await client.query('ROLLBACK');
        await redis.set(lockKey, '1', 'EX', 86400);
        return { skipped: true, reason: 'already_committed_pg' };
      }

      await client.query(
        `INSERT INTO crm_customer_events (phone_e164, last_event_type, last_occurred_at, raw_payload)
         VALUES ($1, $2, $3, $4)
         ON CONFLICT (phone_e164) DO UPDATE
         SET last_event_type = EXCLUDED.last_event_type,
             last_occurred_at = EXCLUDED.last_occurred_at,
             raw_payload = EXCLUDED.raw_payload
         WHERE crm_customer_events.last_occurred_at <= EXCLUDED.last_occurred_at`,
        [evt.entityPhoneE164, evt.eventType, evt.occurredAt, JSON.stringify(evt.payload)]
      );
      await client.query('COMMIT');
      await redis.set(lockKey, '1', 'EX', 86400);
    } catch (err: any) {
      await client.query('ROLLBACK');
      if (err?.statusCode === 400) throw new UnrecoverableError(`Invalid payload schema: ${err.message}`);
      throw err;
    } finally {
      client.release();
      await redis.del(inflightKey);
    }
  },
  {
    connection: redis,
    concurrency: 16,
    limiter: { max: 120, duration: 1000 }, // Backpressure: tối đa 120 jobs/giây bảo vệ API đích
  }
);
